require_once __DIR__ . '/../app/application.php';if(isset($_GET['lang'])&&in_array($_GET['lang'],supportedLanguages(),true))$_SESSION['lang']=$_GET['lang'];if(isAuthenticated())safeRedirect('../portal/');$error=null;
if(requestMethod()==='POST'){verifyCsrfToken();try{$name=trim((string)($_POST['fullname']??''));$email=normalizedEmail($_POST['email']??'');$phone=trim((string)($_POST['phone']??''));$password=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Name and valid email are required.');$errors=passwordValidationErrors($password);if($errors)throw new InvalidArgumentException(implode(' ',$errors));$agency=dbFetchOne("SELECT id FROM agencies WHERE status='active' AND archived_at IS NULL ORDER BY id LIMIT 1");if(!$agency)throw new DomainException('Online registration is temporarily unavailable.');$id=withTransaction(function()use($name,$email,$phone,$password,$agency){dbExecute("INSERT INTO users(fullname,email,email_normalized,phone,password_hash,role,status,password_changed_at)VALUES(:name,:email,:normalized,:phone,:hash,'CUSTOMER','active',NOW())",['name'=>$name,'email'=>$email,'normalized'=>$email,'phone'=>$phone,'hash'=>password_hash($password,PASSWORD_DEFAULT)]);$userId=(int)db()->lastInsertId();$parts=preg_split('/\s+/',trim($name),2);dbExecute("INSERT INTO customers(agency_id,user_id,customer_type,first_name,last_name,phone,phone_normalized,email,email_normalized,status)VALUES(:agency,:user,'individual',:first,:last,:phone_raw,:phone,:email,:normalized,'new')",['agency'=>$agency['id'],'user'=>$userId,'first'=>$parts[0],'last'=>$parts[1]??'Customer','phone_raw'=>$phone,'phone'=>normalizedPhone($phone),'email'=>$email,'normalized'=>$email]);return$userId;});auditLog('customer.self_registered','user',$id,null,['email'=>$email],$agency['id']);$user=dbFetchOne('SELECT * FROM users WHERE id=:id',['id'=>$id]);$user['iduser']=$id;$user['agency_ids']=[];loginUser($user);safeRedirect('../portal/');}catch(InvalidArgumentException|DomainException $exception){$error=$exception->getMessage();}catch(Throwable $exception){reportDatabaseError($exception,'Customer signup failed');$error='Registration is temporarily unavailable.';}}
?><!doctype html><html lang="<?=e(language())?>" dir="<?=language()==='ar'?'rtl':'ltr'?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account</title><link rel="stylesheet" href="../backoffice/assets/app.css"></head><body class="auth-page"><main class="auth-card"><h1>Create customer account</h1><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><label>Full name<input name="fullname" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone"></label><label>Password<input type="password" name="password" required autocomplete="new-password"></label><small>At least 12 characters with upper/lowercase, a number, and a symbol.</small><button class="btn primary">Create account</button></form><div class="auth-links"><a href="login.php?lang=<?=e(language())?>">Already registered?</a><a href="../<?=e(language())?>/">Website</a></div></main></body></html>

